def max_charity_revenue(milk_tea_capacity: int, cake_capacity: int, menu1_price: int, menu1_milk_tea: int, menu1_cake: int, menu2_price: int, menu2_milk_tea: int, menu2_cake: int) -> int:
    # Calculate the net revenue per unit of milk tea and cake for each menu
    net_revenue_per_milk_tea_menu1 = menu1_price / menu1_milk_tea
    net_revenue_per_milk_tea_menu2 = menu2_price / menu2_milk_tea

    net_revenue_per_cake_menu1 = menu1_price / menu1_cake
    net_revenue_per_cake_menu2 = menu2_price / menu2_cake

    # Determine the optimal strategy
    if net_revenue_per_milk_tea_menu1 > net_revenue_per_milk_tea_menu2:
        if net_revenue_per_cake_menu1 > net_revenue_per_cake_menu2:
            # Sell only Menu 1
            max_revenue = min(milk_tea_capacity // menu1_milk_tea, cake_capacity // menu1_cake) * menu1_price
        else:
            # Sell a combination of Menu 1 and Menu 2 to maximize milk tea and cake usage
            max_revenue = 0
            for i in range(milk_tea_capacity // menu1_milk_tea + 1):
                j = (milk_tea_capacity - i * menu1_milk_tea) // menu2_milk_tea
                if i * menu1_cake + j * menu2_cake <= cake_capacity:
                    max_revenue = max(max_revenue, (i + j) * menu1_price + j * menu2_price)
    else:
        if net_revenue_per_cake_menu1 > net_revenue_per_cake_menu2:
            # Sell only Menu 2
            max_revenue = min(milk_tea_capacity // menu2_milk_tea, cake_capacity // menu2_cake) * menu2_price
        else:
            # Sell a combination of Menu 1 and Menu 2 to maximize milk tea and cake usage
            max_revenue = 0
            for i in range(milk_tea_capacity // menu1_milk_tea + 1):
                j = (milk_tea_capacity - i * menu1_milk_tea) // menu2_milk_tea
                if i * menu1_cake + j * menu2_cake <= cake_capacity:
                    max_revenue = max(max_revenue, (i + j) * menu1_price + j * menu2_price)

    return max_revenue

