from typing import *

def count_ap_triplets(n: int, max_sum: int) -> int:
    def is_ap(a: int, b: int, c: int) -> bool:
        return (b - a) == (c - b)

    count = 0
    for a in range(1, n - 1):
        for b in range(a + 1, n):
            c = 2 * b - a
            if c > b and c <= n and a + b + c <= max_sum and is_ap(a, b, c):
                count += 1
    return count

# Test cases
assert count_ap_triplets(100, 150) == 1225
assert count_ap_triplets(10, 30) == 20
