from math import comb

def calculate_win_probability(p: float) -> float:
    def win_series(prob: float, wins: int, losses: int) -> float:
        if losses >= 3:
            return 0
        if wins >= 3:
            return 1
        total = 0
        for i in range(3 - wins):
            total += comb(2 + i, i) * (prob ** wins) * ((1 - prob) ** losses) * prob
        return total

    return round(win_series(p, 3, 0) + win_series(p, 2, 1) + win_series(p, 1, 2), 2)

# Test cases
assert calculate_win_probability(0.4) == 0.32
assert calculate_win_probability(0.5) == 0.5
