from typing import Tuple

def solve_silk_profit(max_production: int, budget: int, brocade_cost: int, brocade_days: int, mulberry_cost: int, mulberry_days: int, labor_cost: int, brocade_price: int, mulberry_price: int) -> float:
    def profit(x: int, y: int) -> float:
        material_cost = x * brocade_cost + y * mulberry_cost
        labor_cost = x * brocade_days * labor_cost + y * mulberry_days * labor_cost
        if material_cost + labor_cost > budget or x + y > max_production:
            return -float('inf')
        return (x * brocade_price + y * mulberry_price) - (material_cost + labor_cost)

    max_profit = -float('inf')
    best_x, best_y = 0, 0
    for x in range(max_production + 1):
        for y in range(max_production + 1 - x):
            current_profit = profit(x, y)
            if current_profit > max_profit:
                max_profit = current_profit
                best_x, best_y = x, y

    return best_x + 3 * best_y

# Test cases
