def calculate_inverse_prob(start: int, end: int) -> int | None:
    if start > end:
        return None

    total_count = end - start + 1
    valid_count = 0

    for num in range(start, end + 1):
        digits = [int(d) for d in str(num).zfill(5)]
        a1, a2, a3, a4, a5 = digits
        if a1 <= a2 + 1 <= a3 - 7 < a4 <= a5 + 2:
            valid_count += 1

    if total_count == 0:
        return None
    return round(1 / (valid_count / total_count))

