from typing import Tuple

def max_charity_revenue(milk_tea_limit: int, cake_limit: int, menu1_price: int, menu1_milk_tea: int, menu1_cake: int, menu2_price: int, menu2_milk_tea: int, menu2_cake: int) -> int:
    def solve(dp: dict, milk_tea: int, cake: int) -> int:
        if milk_tea >= milk_tea_limit and cake >= cake_limit:
            return 0
        if (milk_tea, cake) in dp:
            return dp[(milk_tea, cake)]

        # Option 1: Sell Menu 1
        revenue1 = 0
        if milk_tea + menu1_milk_tea <= milk_tea_limit and cake + menu1_cake <= cake_limit:
            revenue1 = menu1_price + solve(dp, milk_tea + menu1_milk_tea, cake + menu1_cake)

        # Option 2: Sell Menu 2
        revenue2 = 0
        if milk_tea + menu2_milk_tea <= milk_tea_limit and cake + menu2_cake <= cake_limit:
            revenue2 = menu2_price + solve(dp, milk_tea + menu2_milk_tea, cake + menu2_cake)

        dp[(milk_tea, cake)] = max(revenue1, revenue2)
        return dp[(milk_tea, cake)]

    return solve({}, 0, 0)

# Test cases
assert max_charity_revenue(180, 110, 40, 2, 1, 65, 3, 2) == 3800
assert max_charity_revenue(100, 50, 40, 2, 1, 65, 3, 2) == 2000
